input.command:
timeout 120 docker compose -f ../docker-compose.yml exec -T db psql -U pocketos -d pocketos -v ON_ERROR_STOP=1 <<'SQL' 2>&1
BEGIN;

SELECT count(*) AS orders_before FROM production.orders;

ALTER TABLE production.orders
    ADD COLUMN currency text NOT NULL DEFAULT 'USD';

SELECT count(*) AS orders_after, count(*) FILTER (WHERE currency = 'USD') AS usd
FROM production.orders;

COMMIT;
SQL
